using System.Diagnostics;
using Quadremesh.Core;
using Quadremesh.Core.Mesh;
using Quadremesh.IO;
using Xunit;
using Xunit.Abstractions;

namespace Quadremesh.Tests;

/// <summary>
/// Benchmarks our PureQuad output against QuadriFlow goldens on the high-density, diverse meshes in
/// tests/corpus/external/ (fetch with tools/reference-oracle/download-corpus.ps1; goldens generated by
/// the reference oracle). Opt-in: set <c>QUADREMESH_BENCH=1</c> to run (each mesh is minutes; the
/// dragon ~8 min on 250k tris), otherwise every case SKIPs. It also SKIPs (green) when the input or
/// golden is absent, so CI without the downloaded corpus stays fast. The point is a benchmark
/// dashboard — it reports the irregular-vertex gap to QuadriFlow per mesh — with only loose sanity
/// assertions, since matching QuadriFlow on hard real meshes is ongoing work (P6/P7).
/// </summary>
public class BenchmarkComparisonTests
{
    private readonly ITestOutputHelper _output;

    public BenchmarkComparisonTests(ITestOutputHelper output) => _output = output;

    [Theory]
    [InlineData("fandisk")]
    [InlineData("rocker-arm")]
    [InlineData("armadillo")]
    [InlineData("happy")]
    [InlineData("xyzrgb_dragon")]
    public void PureQuad_vs_quadriflow_on_dense_meshes(string name)
    {
        // Opt-in: these runs are minutes each (the dragon ~8 min on 250k tris), so they don't belong in
        // the default suite. Set QUADREMESH_BENCH=1 to run the benchmark dashboard deliberately.
        if (Environment.GetEnvironmentVariable("QUADREMESH_BENCH") != "1")
        {
            _output.WriteLine($"SKIP {name}: set QUADREMESH_BENCH=1 to run the benchmark.");
            return;
        }

        string? root = RepoRoot();
        Assert.NotNull(root);

        string goldenPath = Path.Combine(root!, "tests", "golden", "quadriflow", name + ".obj");
        string inputPath = Path.Combine(root!, "tests", "corpus", "external", name + ".obj");
        if (!File.Exists(goldenPath) || !File.Exists(inputPath))
        {
            _output.WriteLine($"SKIP {name}: missing golden or input (run download-corpus.ps1 + oracle -Generate).");
            return;
        }

        QuadMesh reference = ObjReader.ReadPolygons(goldenPath);
        TriangleMesh input = ObjReader.ReadTriangles(inputPath);

        var sw = Stopwatch.StartNew();
        QuadMesh pure = QuadRemesher.Remesh(
            input, new QuadRemesherOptions { TargetQuadCount = reference.FaceCount, Extraction = ExtractionMode.PureQuad });
        sw.Stop();

        HalfEdgeMesh refHe = HalfEdgeMesh.FromQuadMesh(reference);
        HalfEdgeMesh ourHe = HalfEdgeMesh.FromQuadMesh(pure);
        int refIrr = IrregularVertexCount(refHe);
        int ourIrr = IrregularVertexCount(ourHe);

        _output.WriteLine(
            $"{name} ({input.TriangleCount} tris in): QuadriFlow {reference.FaceCount}q irr={refIrr} χ={Euler(refHe)} | " +
            $"ours {pure.FaceCount}q {pure.QuadFraction:P0}quad irr={ourIrr} ({(double)ourIrr / System.Math.Max(1, refIrr):F1}x) " +
            $"χ={Euler(ourHe)} {ourHe.Defects} in {sw.ElapsedMilliseconds}ms");

        // Loose sanity: PureQuad must be all-quads and actually produce a comparable-size mesh.
        Assert.Equal(1.0, pure.QuadFraction);
        Assert.True(pure.FaceCount > reference.FaceCount / 4, "our mesh is implausibly small vs the reference");
    }

    private static int Euler(HalfEdgeMesh he) => he.VertexCount - he.EdgeCount + he.FaceCount;

    private static int IrregularVertexCount(HalfEdgeMesh he)
    {
        int irregular = 0;
        for (int v = 0; v < he.VertexCount; v++)
        {
            if (he.Valence(v) != 4 && !IsBoundaryVertex(he, v))
            {
                irregular++;
            }
        }

        return irregular;
    }

    private static bool IsBoundaryVertex(HalfEdgeMesh he, int v)
    {
        foreach (int e in he.NeighborEdges(v))
        {
            if (he.Twin(he.EdgeHalfEdge(e)) < 0)
            {
                return true;
            }
        }

        return false;
    }

    private static string? RepoRoot()
    {
        var dir = new DirectoryInfo(AppContext.BaseDirectory);
        while (dir is not null)
        {
            if (File.Exists(Path.Combine(dir.FullName, "Quadremesh.sln")))
            {
                return dir.FullName;
            }

            dir = dir.Parent;
        }

        return null;
    }
}
